<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Your Page</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    html, body {
      height: 100%;
      margin: 0;
    }

    .bg-primary {
      position: relative;
      isolation: isolate;
      overflow: hidden;
      height: 100%;
      background-color: rgba(85, 208, 64, 0.25);
    }

    .bg-primary::before {
      content: '';
      position: absolute;
      width: 100%;
      height: 100%;
      background-color: rgba(85, 208, 64, 0.25);
      z-index: -2;
    }

    .bg-primary::after {
      content: '';
      position: absolute;
      width: 300px;
      height: 150%;
      background: #F9E1C3;
      transform: rotate(25deg);
      transform-origin: left top;
      right: 70px;
      top: -50px;
      filter:
        drop-shadow(2px 4px 24px rgba(0, 0, 0, 0.08))
        blur(50px);
      z-index: -1;
      pointer-events: none;
      opacity: 0.7;
    }

    .btn-primary {
      background-color: #3EB798;
      color: white;
      font-weight: 600;
      padding: 0.5rem 3rem;
      border-radius: 0.900rem;
      transition: background-color 0.2s;
    }

    .btn-primary:hover {
      background-color: #359f83;
    }
  </style>
</head>
